const $=s=>document.querySelector(s);const gcd=(a,b)=>b?gcd(b,a%b):Math.abs(a);function frac(n,d){if(d<0){n=-n;d=-d}const g=gcd(n,d);return d/g===1?String(n/g).replace('-','−'):`${String(n/g).replace('-','−')}/${d/g}`}const storage={get(k){try{return localStorage.getItem('fondasi-powers-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-powers-'+k,v);return true}catch{return false}}};const supers={'-':'⁻','0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵'};const sup=n=>String(n).split('').map(c=>supers[c]).join('');const baseLabel=b=>b===.5?'(1/2)':b<0?`(${String(b).replace('-','−')})`:String(b);function power(){const b=Number($('#base').value),n=Number($('#exponent').value);$('#exponent-out').value=n;$('#factors').replaceChildren();for(let i=0;i<n;i++){if(i){const sign=document.createElement('span');sign.textContent='×';$('#factors').append(sign)}const token=document.createElement('span');token.className='factor';token.textContent=baseLabel(b);$('#factors').append(token)}const result=b===.5?`1/${2**n}`:String(b**n).replace('-','−');$('#power-equation').textContent=`${baseLabel(b)}${sup(n)} = ${result}`;$('#power-feedback').textContent=`Ada ${n} faktor ${baseLabel(b)} yang dikalikan. `+(b<0?`Banyak faktor negatif ${n%2?'ganjil, sehingga hasil negatif.':'genap, sehingga hasil positif.'}`:b===.5?'Setiap perkalian dengan setengah mengambil setengah dari nilai sebelumnya.':b===0?'Karena eksponennya positif, perkalian ini memuat faktor nol dan hasilnya nol.':'Eksponen menghitung faktor, bukan bilangan yang dikalikan langsung dengan basis.')}$('#base').addEventListener('change',power);$('#exponent').addEventListener('input',power);power();function value(b,n){return n>=0?String(b**n).replace('-','−'):frac(1,b**(-n))}function pattern(){const b=Number($('#pattern-base').value),n=Number($('#pattern-exp').value);$('#pattern-out').value=String(n).replace('-','−');$('#pattern-table').replaceChildren();for(let e=-3;e<=3;e++){const item=document.createElement('div');item.className='pattern-item'+(e===n?' active':'');item.setAttribute('role','listitem');const label=document.createElement('span');label.textContent=baseLabel(b)+sup(e);const result=document.createElement('b');result.textContent=value(b,e);item.append(label,result);$('#pattern-table').append(item)}$('#pattern-feedback').textContent=`${baseLabel(b)}${sup(n)} = ${value(b,n)}. `+(n===0?'Pangkat nol bernilai 1 karena basis bukan nol.':n<0?`Ini kebalikan dari ${baseLabel(b)}${sup(-n)}, yaitu 1/(${baseLabel(b)}${sup(-n)}).`:'Eksponen positif berarti perkalian berulang.')+` Jika pangkat turun satu, nilai dibagi ${String(b).replace('-','−')}.`}$('#pattern-base').addEventListener('change',pattern);$('#pattern-exp').addEventListener('input',pattern);pattern();function root(){const a=Number($('#area').value),s=Math.sqrt(a),px=s*48;$('#square').setAttribute('width',px);$('#square').setAttribute('height',px);$('#square').setAttribute('x',180-px/2);$('#square').setAttribute('y',160-px/2);$('#area-label').textContent=`Luas = ${a} satuan persegi`;$('#side-label').textContent=a===2?'Sisi = √2 ≈ 1,4142 satuan':`Sisi = ${s} satuan`;$('#root-feedback').textContent=a===2?'√2 adalah nilai tepat panjang sisi. Pendekatan desimalnya 1,4142. Kuadrat dari pendekatan ini hanya mendekati 2.':a===0?'√0 = 0. Sisi nol memberi luas nol. Persegi ini menyusut menjadi satu titik.':`√${a} = ${s}, karena ${s} × ${s} = ${a}. Akar kuadrat utama dipilih tidak negatif.`}$('#area').addEventListener('change',root);root();
$('#check').addEventListener('click',()=>{const v=document.querySelector('[name=awal]:checked')?.value;$('#check-feedback').textContent=!v?'Pilih satu dugaan terlebih dahulu.':v==='repeat'?'Tepat. Ada empat faktor 3. Nilainya 81.':'3⁴ berarti empat faktor 3 dikalikan, yaitu 3 × 3 × 3 × 3. Perkalian 3 × 4 atau penjumlahan empat bilangan 3 bernilai 12, bukan 81.'});
const qs=[{t:'2⁴ = …',n:16,d:1,h:'Kalikan empat faktor 2.',why:'2 × 2 × 2 × 2 = 16.'},{t:'5⁰ = …',n:1,d:1,h:'Basisnya bukan nol. Gunakan pola pangkat nol.',why:'5⁰ = 1.'},{t:'2⁻³ = …',n:1,d:8,h:'Pangkat negatif menyatakan kebalikan 2³.',why:'2⁻³ = 1/2³ = 1/8.'},{t:'(−2)³ = …',n:-8,d:1,h:'Ada tiga faktor negatif.',why:'(−2) × (−2) × (−2) = −8.'},{t:'2³ × 2² = … (tulis nilai bilangannya)',n:32,d:1,h:'Ada lima faktor 2 seluruhnya.',why:'2³ × 2² = 2⁵ = 32.'},{t:'√16 = …',n:4,d:1,h:'Cari bilangan tidak negatif yang kuadratnya 16.',why:'√16 = 4, karena 4 × 4 = 16.'},{t:'√((−5)²) = …',n:5,d:1,h:'Kuadratkan dahulu. Akar kuadrat utama tidak negatif.',why:'(−5)² = 25, lalu √25 = 5. Ini sama dengan |−5|.'}];const solved=new Set();function progress(){$('#progress').textContent=`${solved.size} dari 8 latihan telah dijawab dengan tepat.`}function parse(s){const m=s.trim().replace(/−/g,'-').match(/^([+-]?\d+)(?:\s*\/\s*([+-]?\d+))?$/);if(!m)return null;const n=Number(m[1]),d=m[2]?Number(m[2]):1;return Number.isSafeInteger(n)&&Number.isSafeInteger(d)&&d!==0&&Math.abs(n)<=1000000&&Math.abs(d)<=1000000?{n,d}:null}$('#questions').innerHTML=qs.map((q,i)=>`<div class="question"><h3>Latihan ${i+1}</h3><p>${q.t}</p><form class="number-form" data-q="${i}"><label for="answer${i}">Jawaban latihan ${i+1}, pecahan atau bilangan bulat</label><div class="answer-line"><input id="answer${i}" type="text" inputmode="text" placeholder="misalnya 1/8" required autocomplete="off" aria-describedby="feedback${i}"><button class="button">Periksa jawaban</button></div></form><p id="feedback${i}" class="feedback" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.h}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('[data-q]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.q),v=parse($('#answer'+i).value),q=qs[i],ok=v&&v.n*q.d===q.n*v.d;$('#feedback'+i).className='feedback '+(ok?'correct':'incorrect');$('#feedback'+i).textContent=!v?'Tulis bilangan bulat atau pecahan seperti -8 atau 1/8. Penyebut tidak boleh nol.':ok?'Tepat. '+q.why:'Belum tepat. Perhatikan basis, pangkat, tanda kurung, serta makna akar. Buka petunjuk jika perlu.';if(ok)solved.add(i);progress()}));$('#check-roots').addEventListener('click',()=>{const v=document.querySelector('[name=roots]:checked')?.value,ok=v==='both';$('#roots-feedback').className='feedback '+(ok?'correct':'incorrect');$('#roots-feedback').textContent=!v?'Pilih satu jawaban terlebih dahulu.':ok?'Tepat. √9 adalah akar utama, yaitu 3. Persamaan x² = 9 meminta semua bilangan yang kuadratnya 9: −3 dan 3.':'Bedakan nilai simbol akar utama dengan semua solusi persamaan. √9 = 3, sedangkan x² = 9 memiliki solusi −3 dan 3.';if(ok)solved.add(7);progress()});$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#reflection-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan pada peramban ini.':'Catatan belum bisa disimpan. Salin jika ingin menyimpannya.'});function completed(){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#progress').textContent='Bacaan ditandai selesai ✓'}if(storage.get('complete')==='yes')completed();$('#complete').addEventListener('click',()=>{const ok=storage.set('complete','yes');completed();$('#complete-note').textContent=ok?'Kemajuan tersimpan. Kamu dapat kembali berlatih kapan saja.':'Selesai. Kemajuan belum bisa disimpan pada peramban ini.'});
